/* eslint-disable */
import React, { useState } from "react";
import { ccc } from "@ckb-ccc/connector-react";

const Counter: React.FC = () => {
  const signer = ccc.useSigner();

  const [txHash, setTxHash] = useState<string>("");
  const [counter, setCounter] = useState<number | null>(null);
  const [outPoint, setOutPoint] = useState<any>(null);

  // -----------------------------
  // Create counter cell
  // -----------------------------
  const createCounter = async () => {
    if (!signer) return;

    const { script: lock } =
      await signer.getRecommendedAddressObj();

    const tx = ccc.Transaction.from({
      outputs: [
        {
          lock,
          capacity: ccc.fixedPointFrom(61),
        },
      ],
    });

    await tx.completeInputsByCapacity(signer);
    await tx.completeFeeBy(signer);

    const hash = await signer.sendTransaction(tx);

    setTxHash(hash);
    setOutPoint({
      tx_hash: hash,
      index: "0x0",
    });

    // empty data → treat as 0
    setCounter(0);
  };

  // -----------------------------
  // Read counter from chain
  // -----------------------------
  const readCounter = async () => {
    if (!outPoint) return;

    const cell = await ccc.client.getCellLive(outPoint, true);
    if (!cell) return;

    if (!cell.outputData || cell.outputData.length === 0) {
      setCounter(0);
      return;
    }

    const hex = Buffer.from(cell.outputData).toString("hex");
    const value = Number(BigInt("0x" + hex));
    setCounter(value);
  };

  // -----------------------------
  // Increment counter on-chain
  // -----------------------------
  const incrementCounter = async () => {
    if (!signer || !outPoint || counter === null) return;

    const newValue = counter + 1;

    // u64 little-endian (8 bytes)
    const hexValue = newValue
      .toString(16)
      .padStart(16, "0");

    const cell = await ccc.client.getCellLive(outPoint, true);
    if (!cell) return;

    const { script: lock } =
      await signer.getRecommendedAddressObj();

    const tx = ccc.Transaction.from({
      inputs: [
        {
          previous_output: outPoint,
        },
      ],
      outputs: [
        {
          lock,
          capacity: cell.cell_output.capacity,
          // CCC typing workaround (safe)
          data: ("0x" + hexValue) as any,
        },
      ],
    });

    await tx.completeFeeBy(signer);

    const hash = await signer.sendTransaction(tx);

    // update to new cell
    setTxHash(hash);
    setOutPoint({
      tx_hash: hash,
      index: "0x0",
    });
    setCounter(newValue);
  };

  return (
    <div className="p-4 border rounded mt-4">
      <h3>On-Chain Counter</h3>

      {counter !== null && (
        <p>Counter Value: {counter}</p>
      )}

      {counter === null && (
        <button disabled={!signer} onClick={createCounter}>
          Create Counter Cell
        </button>
      )}

      {counter !== null && (
        <>
          <button onClick={readCounter}>
            Read From Chain
          </button>

          {counter !== null && (
  <button onClick={incrementCounter}>
    Increment
  </button>
)}

        </>
      )}

      {txHash && (
        <>
          <p style={{ wordBreak: "break-all" }}>
            Tx Hash: {txHash}
          </p>
          <p>
            OutPoint: {outPoint?.tx_hash} : {outPoint?.index}
          </p>
        </>
      )}
    </div>
  );
};

export default Counter;
